# ⭐ 핵심 코드: 키오스크 서버(/ws/kiosk) + 화면(kiosk.html)
READY = {}
def speak(reply, speed=1.0):                             # 늘 같은 답은 한 번 합성해 두고 꺼내 씀 (D44)
    if (reply, speed) not in READY: READY[(reply, speed)] = say(reply, sid=0, speed=speed)
    return READY[(reply, speed)]
for r in list(ASK.values())[:1] + [ASK["more"], ASK["where"]] + [reask(k)[0] for k in (1, 2, 3)]: speak(r)       # 미리 합성

app = FastAPI(title="하나 카페 키오스크")
@app.get("/")
async def page(): return HTMLResponse(open("kiosk.html", encoding="utf-8").read())

@app.websocket("/ws/kiosk")
async def ws_kiosk(ws: WebSocket):
